-- =============================================================================
-- Maintenance records (resolves R-7)
-- =============================================================================
-- Adds MaintenanceRecord with its two enums, the MAINTENANCE numbering scope
-- (MNT-YYYY-NNNNNN) and the maintenance audit actions.
--
-- The first part of this file was generated by `prisma migrate diff` from
-- schema.prisma. The hand-written integrity rules follow it: they express
-- what Prisma's schema language cannot, and Prisma ignores them during drift
-- detection.
--
-- Documented in docs/ARCHITECTURE.md sections 3.6 and 4.7.
-- =============================================================================

-- CreateEnum
CREATE TYPE "MaintenanceType" AS ENUM ('PREVENTIVE', 'REPAIR', 'CALIBRATION', 'SOFTWARE_UPDATE', 'WARRANTY_SERVICE', 'OTHER');

-- CreateEnum
CREATE TYPE "MaintenanceStatus" AS ENUM ('SCHEDULED', 'IN_PROGRESS', 'ON_HOLD', 'COMPLETED', 'CANCELLED');

-- AlterEnum
-- This migration adds more than one value to an enum.
-- With PostgreSQL versions 11 and earlier, this is not possible
-- in a single migration. This can be worked around by creating
-- multiple migrations, each migration adding only one value to
-- the enum.


ALTER TYPE "AuditAction" ADD VALUE 'MAINTENANCE_CREATED';
ALTER TYPE "AuditAction" ADD VALUE 'MAINTENANCE_UPDATED';
ALTER TYPE "AuditAction" ADD VALUE 'MAINTENANCE_STATUS_CHANGED';

-- AlterEnum
ALTER TYPE "NumberScope" ADD VALUE 'MAINTENANCE';

-- CreateTable
CREATE TABLE "maintenance_records" (
    "id" TEXT NOT NULL,
    "maintenanceNumber" TEXT NOT NULL,
    "assetId" TEXT NOT NULL,
    "issueId" TEXT,
    "type" "MaintenanceType" NOT NULL,
    "status" "MaintenanceStatus" NOT NULL DEFAULT 'SCHEDULED',
    "title" TEXT NOT NULL,
    "description" TEXT,
    "scheduledFor" TIMESTAMPTZ(3),
    "startedAt" TIMESTAMPTZ(3),
    "completedAt" TIMESTAMPTZ(3),
    "vendor" TEXT,
    "vendorReference" TEXT,
    "cost" DECIMAL(12,2),
    "currency" VARCHAR(3) NOT NULL DEFAULT 'AED',
    "outcome" TEXT,
    "performedById" TEXT,
    "cancelledAt" TIMESTAMPTZ(3),
    "cancelReason" TEXT,
    "createdById" TEXT NOT NULL,
    "updatedById" TEXT,
    "deletedAt" TIMESTAMPTZ(3),
    "createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMPTZ(3) NOT NULL,

    CONSTRAINT "maintenance_records_pkey" PRIMARY KEY ("id")
);

