CREATE UNIQUE INDEX "maintenance_records_maintenanceNumber_key" ON "maintenance_records"("maintenanceNumber");

-- CreateIndex
CREATE INDEX "maintenance_records_assetId_status_idx" ON "maintenance_records"("assetId", "status");

