-- =============================================================================
-- Hand-written integrity rules
-- =============================================================================

-- -----------------------------------------------------------------------------
-- 1. Work cannot finish before it starts
-- -----------------------------------------------------------------------------
ALTER TABLE "maintenance_records"
  ADD CONSTRAINT "maintenance_records_completed_after_started"
  CHECK (
    "completedAt" IS NULL
    OR "startedAt" IS NULL
    OR "completedAt" >= "startedAt"
  );

-- -----------------------------------------------------------------------------
-- 2. Status and its timestamps agree
-- -----------------------------------------------------------------------------
-- A record is COMPLETED exactly when completedAt is set, CANCELLED exactly when
-- cancelledAt is set, and cannot be IN_PROGRESS without a start time. This
-- stops a UI bug from producing "completed" work with no completion date - the
-- date is what the annual calibration report is built from.
ALTER TABLE "maintenance_records"
  ADD CONSTRAINT "maintenance_records_status_matches_timestamps"
  CHECK (
    ("status" = 'COMPLETED') = ("completedAt" IS NOT NULL)
    AND ("status" = 'CANCELLED') = ("cancelledAt" IS NOT NULL)
    AND ("status" <> 'IN_PROGRESS' OR "startedAt" IS NOT NULL)
  );

-- -----------------------------------------------------------------------------
-- 3. Money is sane
-- -----------------------------------------------------------------------------
ALTER TABLE "maintenance_records"
  ADD CONSTRAINT "maintenance_records_cost_not_negative"
  CHECK ("cost" IS NULL OR "cost" >= 0);

-- ISO 4217 codes are three upper-case letters. The default is AED; the
-- `maintenance.defaultCurrency` setting pre-fills the UI.
ALTER TABLE "maintenance_records"
  ADD CONSTRAINT "maintenance_records_currency_is_iso4217"
  CHECK ("currency" ~ '^[A-Z]{3}$');

-- -----------------------------------------------------------------------------
-- 4. An asset is in at most one workshop at a time
-- -----------------------------------------------------------------------------
-- Several SCHEDULED records per asset are legitimate (annual calibration plus
-- a planned repair). Only one may be actively underway - IN_PROGRESS, or
-- ON_HOLD while it sits at a vendor waiting for parts.
CREATE UNIQUE INDEX "maintenance_records_one_active_per_asset"
  ON "maintenance_records" ("assetId")
  WHERE "deletedAt" IS NULL
    AND "status" IN ('IN_PROGRESS', 'ON_HOLD');

-- -----------------------------------------------------------------------------
-- 5. Dashboard supporting index
-- -----------------------------------------------------------------------------
-- "Maintenance due" and "overdue maintenance" scan only open records; completed
-- and cancelled history stays out of the way permanently.
CREATE INDEX "maintenance_records_open_by_scheduled_for"
  ON "maintenance_records" ("scheduledFor")
  WHERE "deletedAt" IS NULL
    AND "status" IN ('SCHEDULED', 'IN_PROGRESS', 'ON_HOLD');
